function fillSite(){
  const t=$('#manText').value||'';const M=parseManual(t),P=parseSite(t),E=extractEnergy(t,M.area||num($('#sArea').value));
  const has=t.trim().length>0;
  const put=(id,src,v,blank)=>{const el=$('#'+id),tag=$('#'+src);tag.style.color='';
    if(v!=null&&v!==''&&!(typeof v==='number'&&!isFinite(v))){if(!el.dataset.user)el.value=v;tag.textContent=el.dataset.user?'edited':'from manual'}
    else if(el.dataset.user)tag.textContent='edited';
    else if(has){if(blank!==undefined)el.value=blank;tag.textContent='not in manual — enter';tag.style.color='var(--warn)'}
    else tag.textContent=''};
  put('sName','nSrc',P.name,'');put('sCur','cSrc',P.cur);put('sArea','aSrc',M.area,'');put('sHours','hSrc',M.hoursWeek,'');
  put('sBench','bSrc',P.bench,'');put('sHvac','vSrc',E.hvac||P.hvac,'');put('sDem','dSrc',P.dem,'0');put('sRate','rSrc',E.rate||P.rate,'');
  const [c,l]=$('#sCur').value.split('|');CUR=c;LOC=l;
}
/* ---------- indicative NABERS Energy rating ----------
   NABERS places actual ÷ benchmark on a star scale; 6★ is half the emissions of 5★, and the scale is taken as linear
   (each star ≈ 50% of the 5★ level), rounded down to the nearest half star. Gas is converted to electricity-equivalent
   kWh by the ratio of emission factors. Indicative only: no climate, hours or occupancy normalisation. */
function nabStars(kwhe,area,ref){if(!(area>0)||!(ref>0)||!(kwhe>=0))return NaN;const x=kwhe/area/ref;return Math.max(0,Math.min(6,Math.floor((5-2*(x-1))*2)/2))}
const starRow=v=>{let h='';for(let k=1;k<=6;k++)h+=`<i class="${v>=k?'on':v>=k-0.5?'half':''}">★</i>`;return`<span class="xstars" aria-label="${isFinite(v)?v:0} stars">${h}</span>`};
function nabBlock(R){const N=R.NAB;if(!N)return'';
  if(!(N.area>0))return`<div class="xnab"><div class="xnab-h"><h3 style="margin:0">NABERS Energy rating — before &amp; after</h3><span class="meta">Indicative</span></div><p class="meta" style="margin:0">Not estimated: the floor area is not stated. Enter it in Site settings to see the rating.</p></div>`;
  const up=N.a-N.b;
  return`<div class="xnab"><div class="xnab-h"><h3 style="margin:0">NABERS Energy rating — before &amp; after</h3><span class="meta">Indicative estimate · ${esc(N.type)} · 5★ reference ${fmt(N.ref)} kWhe/m²·yr</span></div>
  <div class="xnab-g">
    <div class="xnab-c"><div class="lab">Before · today</div><div class="num">${starTxt(N.b)}</div>${starRow(N.b)}<div class="meta">${fmt(N.beforeI)} kWhe/m²·yr</div></div>
    <div class="xnab-arrow"><b>→</b>${up>0?'+'+fmt(up,1)+'★':'no change'}</div>
    <div class="xnab-c" style="border-color:var(--good)"><div class="lab">After · identified measures</div><div class="num" style="color:var(--good)">${starTxt(N.a)}</div>${starRow(N.a)}<div class="meta">${fmt(N.afterI)} kWhe/m²·yr (−${pct(N.beforeI?1-N.afterI/N.beforeI:0)})</div></div>
  </div>
  <p class="meta" style="margin:8px 0 0">Estimated by placing energy intensity against the 5-star reference on the NABERS scale (6★ = half the emissions of 5★), rounded down to the nearest half star. Not normalised for climate, hours or occupancy — an official rating needs an accredited NABERS assessor.</p></div>`}
function nabers(R,F){
  if(!$('#sNab').checked)return null;
  const ref=num($('#sNabRef').value),type=$('#sNabType').selectedOptions[0].textContent,A=F.A;const gw=A.grid>0?A.gasCo2/A.grid:0.9;
  const before=R.annual+R.gas.annual*gw,after=Math.max(0,R.annual-F.stratK)+Math.max(0,R.gas.annual-(F.stratG||0))*gw;
  const area=R.S.area;
  return{ref,type,area,gw,beforeI:area>0?before/area:NaN,afterI:area>0?after/area:NaN,b:nabStars(before,area,ref),a:nabStars(after,area,ref)};
}
const starTxt=v=>isFinite(v)?(v%1?v.toFixed(1):v.toFixed(1))+'★':'—';
function energySource(){
  const b=parseBills($('#billText').value);
  if(b.rows.length)return{src:'bills',rows:b.rows,err:''};
  const man=$('#manText').value||'';const M=parseManual(man);
  const E=extractEnergy(man,M.area||num($('#sArea').value));
  if(E.rows&&E.rows.length)return{src:'manual',rows:E.rows,err:'',E};
  return{src:'none',rows:[],err:$('#billText').value.trim()?b.err:'No bills, and no annual kWh found in the building manual.',E};
}
const srcTxt=R=>R.billSrc==='none'?'no energy data (add bills or manual energy figures)':R.billSrc==='manual'?`energy figures from the building manual${R.EX&&R.EX.flat?' (annual total, monthly profile estimated)':''}`:`${R.rows.length} months of bills`;
const sentences=t=>t.split(/(?<=[.!?])\s+|\n+/).map(s=>s.trim()).filter(Boolean);
function feature(t,f){
  if(!f)return{state:'absent',quote:''};
  const ss=sentences(t).filter(s=>f.subj.test(s));
  if(!ss.length)return{state:'absent',quote:''};
  const yes=ss.find(s=>f.pos.test(s)&&!/\b(no|not|without|fixed)\b/i.test(s));
  return yes?{state:'yes',quote:yes}:{state:'no',quote:ss[0]};
}
function autoNA(M,t){
  const eqOn=BASIS==='G36'?g36Equip(t||''):null;
  const rule=p=>{if(p.sub==='Heating'||['AHU-HWV','VAV-RHV','ZN-HSP','BLR-FIRE'].includes(p.tag))return !M.has.heating;if(p.tag==='GAS-M')return !M.has.gas&&!M.has.heating;if(p.eq==='Air-cooled condenser')return !M.has.aircooled;if(p.eq==='Carpark')return !M.has.carpark;if(/^EEV-/.test(p.tag))return !M.has.dx;return false};
  WB.P.forEach(p=>{const st=ST[p.tag];if(!st||st.user)return;const na=p.g36?!g36Applicable(p,t||'',eqOn):rule(p);if(na)st.s=3;else if(st.s===3&&st.auto)st.s=0;st.auto=na})
}

