  appS.filter(s=>s.missingRoles.length).forEach(s=>{const crit=s.missingRoles.filter(r=>r!=='Input');G({layer:'D',title:`#${s.n} ${s.name}: design missing ${s.missingRoles.join(', ')} point${s.missingRoles.length>1?'s':''}`,standard:BASIS==='G36'?'Each G36-traced strategy needs input, output and feedback points from its §5 clauses':s.mgmt?'Management strategies need a trigger and an M&V measure (OEH strategy 17–20; ASHRAE G14)':'Each control strategy needs trigger, input, constraint, output, feedback, safety and M&V links',observed:`Traceability links present: ${[...s.roles].join(', ')||'none'}`,evidence:[BASIS==='G36'?'G36 clause trace':'Traceability sheet'],action:s.missingRoles.includes('M&V')?`Add an M&V point (sub-meter kW/kWh or KPI register) so ${s.name.toLowerCase()} savings can be proven.`:s.missingRoles.includes('Trigger')?'Define the trigger point that decides when the strategy acts.':`Add ${s.missingRoles.join(', ').toLowerCase()} link(s) to the strategy design.`,priority:crit.length?'Medium':'Low'})});
  if(conf.length)G({layer:'D',title:`${conf.length} points written by more than one strategy`,standard:'Single owner or explicit priority per write point (BACnet priority 13 for AI, below operator 8)',observed:`${conf.map(c=>c.tag).join(', ')}; arbitration rules ${confDefined===conf.length?'defined in matrix':'missing for '+(conf.length-confDefined)}`,evidence:[BASIS==='G36'?'G36 output owners':'Write Conflicts sheet'],action:'Implement each arbitration rule in the AI dispatcher and BMS, then witness-test mode changes (e.g. night purge releasing before OSS start).',priority:'High'});
  if(contradict.length)G({layer:'D',title:`Site manual hard-codes ${contradict.length} values the optimisation design expects to reset`,standard:B.resetStd,observed:contradict.map(s=>`#${s.n} ${s.name}`).join('; '),evidence:BASIS==='G36'?['Manual','G36 §5 sequences']:['Manual','Strategies sheet'],action:BASIS==='G36'?'Update the building user manual and sequence of operation so fixed setpoints are reset by the G36 §5 trim & respond logic within its limits.':'Update the building user manual and BMS functional description so fixed setpoints become AI-writable within the matrix guard-rails.',priority:'High'});
  if(isFinite(M.zoneSP)&&(M.zoneSP<22||(M.deadband!=null&&M.deadband<2)))G({layer:'D',title:`Zone setpoint ${M.zoneSP} °C${M.deadband!=null?' with '+M.deadband+' °C deadband':''} conflicts with design band`,standard:B.zoneStd,observed:`Manual: ${M.zoneSP} °C fixed${M.deadband!=null?', deadband '+M.deadband+' °C':''}`,evidence:BASIS==='G36'?['Manual','G36 §5.3']:['Manual','Strategies sheet'],action:BASIS==='G36'?'Adopt G36 §5.3 occupied heating / cooling setpoints with unoccupied setback and setup; let the zone setpoint be reset by sequence.':'Adopt the 22–24 °C adaptive band with after-hours setback; release ZN-CSP for AI writes.',priority:'High'});

  /* SYSTEM */
  const domScore={};DOMAINS.concat([...new Set(WB.S.map(s=>s.dom))].filter(d=>!DOMAINS.includes(d))).forEach(d=>{const ss=appS.filter(s=>s.dom===d);if(!ss.length)return;const w=s=>{const m=String(s.save||'').match(/(\d+)/);return m?+m[1]:10};domScore[d]=ss.reduce((a,s)=>a+w(s)*ACH[s.status],0)/ss.reduce((a,s)=>a+w(s),0)});
  const domAvg=Object.values(domScore).reduce((a,b)=>a+b,0)/(Object.keys(domScore).length||1);
  const euiS=isFinite(EUI)?clamp(100-Math.max(0,EUI/S.bench-1)*110,10,100):50;
  const lfS=isFinite(LF)?clamp(100-Math.max(0,LF-expLF)*450,10,100):60;
  const sScore=Math.round(60*domAvg+0.4*(euiS+lfS)/2);
  appS.filter(s=>!['active'].includes(s.status)).forEach(s=>{G({layer:'S',strat:s.n,title:`#${s.n} ${s.name} — ${STATUS[s.status].toLowerCase()}`,standard:BASIS==='G36'?`G36 §${(G36X[s.n]||{sec:[]}).sec.join(', §')} sequence for OEH #${s.n} (${s.dom}); guide max ${s.save}`:`OEH strategy #${s.n} (${s.dom}); guide max ${s.save}`,observed:(s.mf.state==='no'?`Manual: “${s.mf.quote.slice(0,120)}”`:s.mf.state==='yes'?'Manual describes it; points not verified':'Not described in manual')+` · point readiness ${pct(s.rd)}`,evidence:['Manual',BASIS==='G36'?'G36 clause trace':'Traceability',s.miss.length?`Missing ${s.miss.length} point(s)`:'Points available'],action:s.status==='ready'?`Enable: ${s.act}. ${s.cx||''}`:s.status==='unverified'?`Map and verify ${s.miss.slice(0,5).join(', ')} to prove the sequence runs.`:`Map ${s.miss.slice(0,6).join(', ')}${s.miss.length>6?' +'+(s.miss.length-6):''}, then enable ${s.act.toLowerCase()}.`,kwh:s.kwh,gkwh:s.gkwh,wkl:s.wkl,cost:s.cost,priority:s.status==='ready'||s.cost>cost*0.02?'High':s.status==='unverified'?'Low':'Medium',phase:s.phase})});
  if(isFinite(EUI)&&EUI>S.bench*1.05)G({layer:'S',title:'Energy use intensity above benchmark',standard:`Benchmark ${fmt(S.bench)} kWh/m²·yr`,observed:`${fmt(EUI)} kWh/m²·yr (${fmt((EUI/S.bench-1)*100)}% above)`,evidence:['Bills','Manual (area)'],action:'Headline outcome gap; the strategy gaps above close part of it.',priority:'High',note:'headline'});
  if(isFinite(LF)&&LF-expLF>0.03)G({layer:'S',title:'Plant running outside occupied hours',standard:`Expected load factor ≈ ${fmt(expLF,2)} for ${fmt(S.hours)} h/week`,observed:`Average load factor ${fmt(LF,2)}`,evidence:['Bills','Manual (hours)'],action:BASIS==='G36'?'Covered by G36 §5.4 / §5.15 scheduling, warm-up and setback; check 24/7 loads and after-hours overrides.':'Covered by #1 OSS and #2 setback; check 24/7 loads and after-hours overrides.',priority:'High',note:BASIS==='G36'?'see G36 §5.4':'see #1, #2'});
  if(isFinite(avgPF)&&avgPF<0.97&&S.dem>0){const sv=rows.reduce((a,r)=>a+(isFinite(r.kw)&&isFinite(r.pf)?Math.max(0,r.kw/r.pf-r.kw/0.99):0),0)*S.dem*scale*(M.contract&&maxKva<M.contract*0.75?0.3:1);G({layer:'S',title:'Power factor below 0.97',standard:'Target 0.98–0.99',observed:`Average PF ${fmt(avgPF,2)}`,kind:'pf',evidence:['Bills'],action:'Service APFC panels; target 0.99.',cost:sv,priority:avgPF<0.95?'High':'Medium'})}
  if(M.contract&&maxKva>0&&maxKva<M.contract*0.8){const sv=Math.max(0,M.contract*0.75-maxKva*1.1*0.75)*S.dem*12;G({layer:'S',title:'Contract demand set too high',standard:'Contract ≈ 1.1 × recorded maximum',observed:`Contract ${fmt(M.contract)} kVA vs max ${fmt(maxKva)} kVA`,kind:'cd',evidence:['Manual','Bills'],action:`Reduce contract demand to about ${fmt(Math.ceil(maxKva*1.1/50)*50)} kVA.`,cost:sv,priority:'High'})}

  /* SUBSYSTEM */
  const subs={};WB.P.forEach(p=>{const g=subs[p.sub]=subs[p.sub]||{name:p.sub,n:0,na:0,map:0,ver:0,w:0,v:0,missing:[]};g.n++;const s=ST[p.tag].s;if(s===3){g.na++;return}const w=Math.max(1,p.uses);g.w+=w;g.v+=w*STV[s];if(s>=1)g.map++;if(s===2)g.ver++;if(s===0)g.missing.push(p)});
  const subArr=Object.values(subs).map(g=>({...g,cov:g.w?g.v/g.w:null})).sort((a,b)=>(a.cov??2)-(b.cov??2));
  const subLive=subArr.filter(g=>g.cov!=null);
  const bScore=Math.round(100*subLive.reduce((a,g)=>a+g.cov*g.w,0)/(subLive.reduce((a,g)=>a+g.w,0)||1));
  subLive.filter(g=>g.cov<0.7).forEach(g=>{const top=g.missing.slice().sort((a,b)=>b.uses-a.uses);const ul=new Set();top.forEach(p=>unlockFor(p.tag).list.forEach(x=>ul.add(x)));G({layer:'B',title:`${g.name}: ${pct(g.cov)} weighted coverage`,standard:B.pointStd,observed:`${g.missing.length} of ${g.n-g.na} points not mapped; top: ${top.slice(0,5).map(p=>p.tag).join(', ')}`,evidence:['Points register'],action:`Map ${top.slice(0,4).map(p=>p.tag).join(', ')} first (used by most strategies).`,priority:g.cov<0.5?'High':'Medium',unlock:[...ul].reduce((a,n)=>a+(SB[n]?SB[n].cost:0),0),unlockList:[...ul]})});

  /* SENSOR */
  const rPts=WB.P.filter(p=>/R/.test(p.dir)&&ST[p.tag].s!==3);
  let sw=0,sv=0;WB.L.filter(l=>/R/.test(l.rw)&&!isNA(l.tag)&&SB[l.s]&&SB[l.s].app).forEach(l=>{const w=ROLEW[l.role]||0.7;sw+=w;sv+=w*val(l.tag)});
  const senCov=sw?sv/sw:0;const senMapped=rPts.filter(p=>ST[p.tag].s>=1).length,senVer=rPts.filter(p=>ST[p.tag].s===2).length;
  const nScore=Math.round(100*(0.7*senCov+0.3*(rPts.length?senVer/rPts.length:0)));
  const missSen=rPts.filter(p=>ST[p.tag].s===0).map(p=>{const u=unlockFor(p.tag);const roles=[...new Set((WB.linksByTag[p.tag]||[]).map(l=>l.role))];return{p,u,roles}}).sort((a,b)=>b.u.list.length-a.u.list.length||b.u.value-a.u.value);
  missSen.slice(0,8).forEach(({p,u,roles})=>G({layer:'N',title:`Sensor ${p.tag}${p.stag?' ('+p.stag+')':''} not mapped — ${p.desc}`,standard:`Read point for ${u.list.length} strateg${u.list.length===1?'y':'ies'} (${roles.join(', ')}); ${B.sensorStd}`,observed:`${p.sub} · ${p.obj} · ${p.unit||''}`,evidence:['Points register','Traceability'],action:/calculated/i.test(p.desc)?'Create the calculated point in the BMS or AI layer.':/API|Data object|Config/.test(p.obj)?'Set up the data integration.':'Map to the BACnet object; install the sensor if absent.',priority:roles.some(r=>['Trigger','Feedback','Safety','Constraint'].includes(r))&&u.list.length>=2?'High':'Medium',unlock:u.value,unlockList:u.list}));
  if(senMapped-senVer>0)G({layer:'N',title:`${senMapped-senVer} mapped sensors not verified`,standard:B.verifyStd,observed:`${senVer} of ${rPts.length} read points verified`,evidence:['Points register (Verified column)'],action:'Run end-to-end checks (field value vs BMS vs AI) and set Verified = Y in the matrix.',priority:'Medium'});

