  const outCov=cw?cv/cw:0;
  const ctrl=appS.filter(s=>!s.mgmt);const closed=ctrl.filter(s=>s.fbMapped&&s.outsMapped);
  const safeOk=BASIS==='G36'?[...new Set(WB.L.filter(l=>l.role==='Safety'&&SB[l.s]&&SB[l.s].app).map(l=>l.tag))].filter(t=>ST[t]&&ST[t].s!==3):SAFETY_TAGS.filter(t=>WB.byTag[t]);const safeMapped=safeOk.filter(t=>val(t)>0);
  const safety=safeOk.length?safeMapped.length/safeOk.length:0;
  const activeFrac=appS.length?appS.filter(s=>s.status==='active'||s.status==='unverified').length/appS.length:0;
  const cScore=Math.round(100*(0.35*outCov+0.25*(ctrl.length?closed.length/ctrl.length:0)+0.2*safety+0.2*activeFrac));
  const safeMiss=safeOk.filter(t=>val(t)===0);
  if(safeMiss.length)G(BASIS==='G36'?{layer:'C',title:`${safeMiss.length} G36 safety and alarm points not mapped`,standard:'G36 §4 protective inputs (freeze, emergency, fault and alarm points) referenced by §5 sequences',observed:`${safeMapped.length} of ${safeOk.length} mapped; missing ${safeMiss.slice(0,6).join(', ')}${safeMiss.length>6?' +'+(safeMiss.length-6):''}`,evidence:['Point_Mapping','Traceability_Matrix'],action:'Map these points before AI writes; protective sequences and alarms cannot be verified without them.',priority:'High',unlock:appS.reduce((a,s)=>a+s.cost,0),unlockList:appS.map(s=>s.n)}:{layer:'C',title:`AI safety layer incomplete: ${safeMiss.join(', ')} not mapped`,standard:'Matrix write rule: AI writes at priority 13, releases on disable or heartbeat loss > 5 min',observed:`${safeMapped.length} of ${safeOk.length} safety points mapped`,evidence:['Legend','Points register'],action:'Map AI enable and heartbeat; configure BMS fallback to local schedules on heartbeat loss. No AI writes until done.',priority:'High',unlock:appS.reduce((a,s)=>a+s.cost,0),unlockList:appS.map(s=>s.n)});
  const open=ctrl.filter(s=>!(s.fbMapped&&s.outsMapped));
  if(open.length)G({layer:'C',title:`${open.length} control strategies cannot run closed loop`,standard:'Each write needs a mapped output and a feedback point to confirm the result',observed:open.map(s=>`#${s.n}${!s.outsMapped?' (output)':''}${!s.fbMapped?' (feedback)':''}`).join(', '),evidence:['Traceability','Points register'],action:'Map the missing output and feedback points; witness-test each write against its commissioning test.',priority:'High'});
  const missW=wPts.filter(p=>ST[p.tag].s===0).sort((a,b)=>b.nW-a.nW);
  missW.slice(0,6).forEach(p=>{const u=unlockFor(p.tag);G({layer:'C',title:`Write point ${p.tag}${p.stag?' ('+p.stag+')':''} not mapped — ${p.desc}`,standard:`Output for ${p.nW} strateg${p.nW===1?'y':'ies'}`,observed:`${p.sub} · ${p.obj}`,evidence:['Points register'],action:`Expose ${p.tag} as a writable ${p.obj} with a relinquish default; test at priority 13.`,priority:p.nW>=2?'High':'Medium',unlock:u.value,unlockList:u.list})});

  const scores={D:dScore,S:sScore,B:bScore,N:nScore,C:cScore};
  const overall=Math.round(LAYERS.reduce((a,l)=>a+scores[l.k],0)/5);
  const pr={High:0,Medium:1,Low:2};gaps.sort((a,b)=>pr[a.priority]-pr[b.priority]||(b.cost+b.unlock*0.01)-(a.cost+a.unlock*0.01));
  const totG=strat.reduce((a,s)=>a+s.gkwh,0),totW=strat.reduce((a,s)=>a+s.wkl,0);
  const totK=strat.reduce((a,s)=>a+s.kwh,0),totC=gaps.reduce((a,g)=>a+(g.cost||0),0);

  /* correlations — point references from the active basis only */
  const G3=BASIS==='G36';
  const grpPt=st=>{const a=WB.P.filter(p=>(p.stag||p.tag)===st&&ST[p.tag]&&ST[p.tag].s!==3);if(!a.length)return null;const m=a.filter(p=>ST[p.tag].s>=1).length;return a.length===1?`${st} ${STNAME[ST[a[0].tag].s].toLowerCase()}`:`${st} ${m}/${a.length} mapped`};
  const ptsTxt=list=>list.map(grpPt).filter(Boolean).join(', ')||`No ${B.short} point for this check`;
  const CP=G3?{hours:['ZN-OCC','ZN-T'],comfort:['ZN-T','ZN-TSP-ADJ'],meter:[]}:{hours:['OSS-START','ZN-OCC'],comfort:['ZN-CSP'],meter:['EM-HVAC-KW']};
  const corr=[];
  const hrsBad=isFinite(LF)&&LF-expLF>0.03;
  corr.push({key:'hours',topic:'Operating hours vs consumption',manual:M.hoursText||`Not stated (assuming ${S.hours} h/week)`,data:isFinite(LF)?`Load factor ${fmt(LF,2)} vs expected ${fmt(expLF,2)}`:'No demand data',points:ptsTxt(CP.hours),ok:!hrsBad,verdict:hrsBad?(G3?'Consumption implies plant runs beyond documented hours; G36 §5.4 / §5.15 scheduling, warm-up and setback are not in place.':'Consumption implies plant runs beyond documented hours; strategy #1 and #2 setback are not in place.'):'Consistent with documented hours.'});
  const spBad=isFinite(M.zoneSP)&&M.zoneSP<23;
  corr.push({key:'comfort',topic:'Comfort setpoint vs seasonal load',manual:isFinite(M.zoneSP)?`${M.zoneSP} °C, deadband ${M.deadband??'?'} °C`:'Not stated',data:isFinite(swing)?`Summer swing ${pct(swing)}`:'—',points:ptsTxt(CP.comfort),ok:!spBad,verdict:spBad?(G3?'Low fixed setpoint amplifies cooling-season load; apply G36 §5.3 occupied and unoccupied setpoint limits.':'Low fixed setpoint amplifies cooling-season load; the #2 band can be applied as ZN-CSP is writable.'):'Setpoint within design band.'});
  const fixedN=ctrlApp.filter(s=>s.mf.state==='no');const readyFixed=fixedN.filter(s=>s.rd>=0.6);
  corr.push({key:'seq',topic:'Manual sequences vs '+(G3?'G36 point readiness':'matrix readiness'),manual:`${fixedN.length} of ${ctrlApp.length} control strategies documented as fixed / disabled`,data:'—',points:`${readyFixed.length} of those have ≥ 60% points ready`,ok:!fixedN.length,verdict:readyFixed.length?`Quick wins: ${readyFixed.map(s=>'#'+s.n).join(', ')} can be enabled with little new hardware.`:'No low-hanging control changes.',fixed:fixedN,ready:readyFixed});
  if(M.contract)corr.push({key:'contract',topic:'Contract demand vs metered demand',manual:`Contract ${fmt(M.contract)} kVA`,data:`Max ${fmt(maxKva)} kVA`,points:ptsTxt(CP.meter),ok:!(maxKva<M.contract*0.8),verdict:maxKva<M.contract*0.8?'Over-contracted; minimum billing on unused capacity.':'Appropriately sized.'});
  let mtN,mtM,mtTxt;
  if(G3){const a=WB.P.filter(p=>/FILT-DP$|-ALM$|-FLT$/.test(p.stag||'')&&ST[p.tag]&&ST[p.tag].s!==3);mtN=a.length;mtM=a.filter(p=>ST[p.tag].s>=1).length;mtTxt=`${mtM} of ${mtN} filter-pressure and fault / alarm points mapped (G36 §4)`}
  else{const mt=['AHU-FLT-DP','RUNHRS','CMMS-WO','FAN-VIB'].filter(t=>WB.byTag[t]);mtN=mt.length;mtM=mt.filter(t=>val(t)>0).length;mtTxt=`${mtM} of ${mtN} condition points mapped (${mt.join(', ')})`}
