    <div class="tblwrap tall"><table><thead><tr><th>${BASIS==='G36'?'Equip.':'Pt'}</th><th>${BASIS==='G36'?'Point ID / tag':'Tag'}</th><th>Description</th><th>Subsystem</th><th>Object</th><th class="c">Dir</th><th class="c">Strategies R / W</th><th style="min-width:120px">Status</th><th style="min-width:150px">Site object reference</th></tr></thead><tbody id="regBody"></tbody></table></div>
